#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (PolyBench sizes & DATA_TYPE)
#include "defines.hpp"

// include benchmark-specific definitions (N, DATA_TYPE, etc)
#include "ludcmp.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize A, b, x, y the same way as the original C init_array().
 *
 * Original C:
 *   for i:
 *     x[i] = 0;
 *     y[i] = 0;
 *     b[i] = (i+1)/fn/2.0 + 4;
 *
 *   A initial lower-triangular construction, then:
 *     B = A * A^T;
 *     A = B;
 *
 * We keep the math identical but add a simple schedule to the SPD
 * construction for better locality (this is outside the timed region).
 *
 * Layout note:
 *   We interpret A(i,j) (row i, column j) as Buffer A(j, i):
 *     - Buffer dimension 0 (x) is the column index, contiguous in memory
 *     - Buffer dimension 1 (y) is the row index
 *   This is row-major for the logical matrix (row-major in j for fixed i).
 */
static void init_array(int n,
                       Halide::Buffer<num_t, 2> &A,   // shape (n, n): (x=col, y=row)
                       Halide::Buffer<num_t, 1> &b,   // shape (n)
                       Halide::Buffer<num_t, 1> &x,   // shape (n)
                       Halide::Buffer<num_t, 1> &y) { // shape (n)
    Var i("i"), col("col"), row("row");

    // Initialize x and y to 0, b[i] = (i+1)/n/2 + 4
    Func init_x("init_x"), init_y("init_y"), init_b("init_b");

    Expr n_expr = Expr(n);

    init_x(i) = cast<num_t>(Expr(0.0));
    init_y(i) = cast<num_t>(Expr(0.0));

    // term = (i+1)/n/2 + 4
    Expr term1 = cast<num_t>(i + 1) / cast<num_t>(n_expr);
    Expr term2 = term1 / cast<num_t>(Expr(2.0));
    Expr term3 = term2 + cast<num_t>(Expr(4.0));
    init_b(i) = term3;

    init_x.realize(x);
    init_y.realize(y);
    init_b.realize(b);

    // Initial lower-triangular A, with A[i][j] = (-j % n) / n + 1 for j <= i,
    // 0 otherwise, and A[i][i] = 1.
    //
    // We store A(row=i, col=j) at A(j, i), i.e., first dimension is column,
    // second is row.
    Func A_init("A_init");

    // (-j % n) / n + 1  -> implement as - (j % n) / n + 1
    Expr neg_mod = -(col % n);
    Expr base = cast<num_t>(neg_mod) / cast<num_t>(n_expr) + cast<num_t>(Expr(1.0));

    // col = j, row = i
    A_init(col, row) =
        select(col == row,
               cast<num_t>(Expr(1.0)),                      // diagonal = 1
               select(col <= row,
                      base,                                 // lower triangle (including diagonal before override)
                      cast<num_t>(Expr(0.0))));             // upper triangle = 0

    // Make the matrix positive semi-definite: B = A * A^T, then A = B.
    //
    // B[r][s] = sum_t A[r][t] * A[s][t]
    // In our layout: A(r, t) is A[row=r, col=t], so:
    // B(row=r, col=s) = sum_t A_init(t, r) * A_init(t, s)
    Func SPD("SPD");
    RDom t_dom(0, n, "t_dom");

    SPD(col, row) = cast<num_t>(Expr(0.0));
    SPD(col, row) += A_init(t_dom, row) * A_init(t_dom, col);

    // A simple schedule for SPD (not in the timed region, but cheap to add).
    Target init_target = get_jit_target_from_environment();
    int vec = init_target.natural_vector_size(type_of<num_t>());

    Var co("co"), ro("ro"), ci("ci"), ri("ri");
    const int tile = 32;
    SPD
        .compute_root()
        .tile(col, row, co, ro, ci, ri, tile, tile)
        .parallel(ro)
        .vectorize(ci, vec);

    // Realize SPD into A buffer (shape n x n).
    SPD.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers:
    // A: 2D (n x n), first dimension = column (j), second = row (i)
    // b, x, y: 1D (n)
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 1> b(n), x(n), y(n);

    // Extra 1D buffer to hold reciprocals of U-diagonal entries.
    // This lets us replace divides by A[i][i] with multiplies, which
    // are much cheaper on modern CPUs.
    Halide::Buffer<num_t, 1> diag_inv(n);

    // Initialize data (outside the timed region).
    init_array(n, A, b, x, y);

    // Set up Halide parameters and ImageParams for the kernel.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam b_param(type_of<num_t>(), 1, "b_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");
    ImageParam y_param(type_of<num_t>(), 1, "y_param");
    ImageParam diag_inv_param(type_of<num_t>(), 1, "diag_inv_param");

    Param<int> pi("pi");  // current i (row)
    Param<int> pj("pj");  // current j (column) for scalar L-updates
    Param<int> pn("pn");  // n (for convenience in ranges)

    A_param.set(A);
    b_param.set(b);
    x_param.set(x);
    y_param.set(y);
    diag_inv_param.set(diag_inv);
    pn.set(n);

    // -----------------------------------------------------------
    // Halide helpers for the LU decomposition and fwd/back solve.
    //
    // We follow the scalar algorithm but factor out as much work
    // as possible into vectorized Halide pipelines:
    //
    // 1) update_L(pi, pj): compute single L entry A[pi][pj] (pj < pi)
    // 2) update_U_row(pi): compute entire U row i (all columns j)
    // 3) compute_y(pi):    forward-substitution y[pi]
    // 4) compute_x(pi):    backward-substitution x[pi]
    //
    // For (2) we compute the whole row in one Halide call to exploit
    // vectorization and parallelism across j; for (1), (3), (4) the
    // loop-carried dependencies in i or j force scalar updates, but
    // we still vectorize the inner dot products.
    // -----------------------------------------------------------

    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());
    const int tile_j = 64; // tile size for j in row kernels

    // 1) L-part update:
    //
    // For j < i:
    //   w = A[i][j];
    //   for k = 0..j-1: w -= A[i][k] * A[k][j];
    //   A[i][j] = w / A[j][j];
    //
    // In our layout: A[i][j] == A_param(j, i).
    // We compute:
    //   A_param(j, i) - sum_{k=0..j-1} A_param(k, i) * A_param(j, k)
    // and then multiply by diag_inv[j] = 1 / A[j][j].
    //
    // We express the inner sum as an explicit reduction 'dot_L' so
    // we can schedule it (vectorize over k).
    Func dot_L("dot_L"), update_L("update_L");
    {
        RDom rL(0, pj, "rL");
        dot_L() = cast<num_t>(Expr(0.0));
        dot_L() += A_param(rL, pi) * A_param(pj, rL);
        update_L() = (A_param(pj, pi) - dot_L()) * diag_inv_param(pj);

        dot_L.compute_root();
        dot_L.update().vectorize(rL, vec_width);
    }

    // 2) U-part update, per entire row:
    //
    // For j >= i:
    //   w = A[i][j];
    //   for k = 0..i-1: w -= A[i][k] * A[k][j];
    //   A[i][j] = w;
    //
    // In our layout: A[i][j] == A_param(j, i).
    // new A[i][j] = A_param(j, i) - sum_{k=0..i-1} A_param(k, i) * A_param(j, k).
    //
    // All columns j are independent given row i's L entries, so we
    // compute the entire row with a single 1D Func 'update_U_row(j)'.
    // We still only copy results back into A for j >= i to preserve
    // the algorithm, but this lets Halide vectorize across j and k.
    Var j("j");
    Func dot_U("dot_U"), update_U_row("update_U_row");
    {
        RDom rU(0, pi, "rU");
        dot_U(j) = cast<num_t>(Expr(0.0));
        dot_U(j) += A_param(rU, pi) * A_param(j, rU);
        update_U_row(j) = A_param(j, pi) - dot_U(j);

        // Schedule: compute dot_U and update_U_row at root, tile and
        // parallelize across j, vectorize inner j.
        Var jo("jo"), ji("ji");
        dot_U
            .compute_root()
            .split(j, jo, ji, tile_j)
            .parallel(jo)
            .vectorize(ji, vec_width);
        dot_U.update()
            .reorder(j, rU)
            .split(j, jo, ji, tile_j)
            .parallel(jo)
            .vectorize(ji, vec_width);

        update_U_row
            .compute_root()
            .split(j, jo, ji, tile_j)
            .parallel(jo)
            .vectorize(ji, vec_width);
    }

    // 3) Forward substitution for y:
    //
    // For i = 0..n-1:
    //   w = b[i];
    //   for j = 0..i-1: w -= A[i][j] * y[j];
    //   y[i] = w;
    //
    // y[i] = b[i] - sum_{j=0..i-1} A[i][j] * y[j].
    // In our layout: A[i][j] == A_param(j, i).
    Func dot_Y("dot_Y"), compute_y("compute_y");
    {
        RDom rY(0, pi, "rY");
        dot_Y() = cast<num_t>(Expr(0.0));
        dot_Y() += A_param(rY, pi) * y_param(rY);
        compute_y() = b_param(pi) - dot_Y();

        dot_Y.compute_root();
        dot_Y.update().vectorize(rY, vec_width);
    }

    // 4) Back substitution for x:
    //
    // For i = n-1..0:
    //   w = y[i];
    //   for j = i+1..n-1: w -= A[i][j] * x[j];
    //   x[i] = w / A[i][i];
    //
    // We rewrite using diag_inv[i] = 1 / A[i][i]:
    //   x[i] = (y[i] - sum_{j=i+1..n-1} A[i][j] * x[j]) * diag_inv[i].
    //
    // sum domain j = i+1 .. n-1  -> RDom(pi+1, n-(pi+1))
    // In our layout: A[i][j] == A_param(j, i).
    Func dot_X("dot_X"), compute_x("compute_x");
    {
        RDom rX(pi + 1, pn - (pi + 1), "rX");
        dot_X() = cast<num_t>(Expr(0.0));
        dot_X() += A_param(rX, pi) * x_param(rX);
        compute_x() = (y_param(pi) - dot_X()) * diag_inv_param(pi);

        dot_X.compute_root();
        dot_X.update().vectorize(rX, vec_width);
    }

    // Compile the helper pipelines once.
    update_L.compile_jit(target);
    update_U_row.compile_jit(target);
    compute_y.compile_jit(target);
    compute_x.compile_jit(target);

    // ------------------------------------
    // Run the kernel and measure its time.
    // ------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // Temporary 1D buffer reused for U row updates to avoid repeated
    // allocation inside the critical loops.
    Halide::Buffer<num_t, 1> u_row_tmp(n);

    // LU decomposition without pivoting.
    //
    // We keep the outer i-loop and L-part j-loop in C++ to respect
    // the strict data dependencies, but:
    //   - L scalar updates use a vectorized reduction over k
    //   - U updates for a given row i are fused into one Halide call
    //     that computes all columns j for that row, exploiting
    //     vectorization and parallelism across j.
    for (int i = 0; i < n; i++) {
        // L-part: j < i
        for (int j_col = 0; j_col < i; j_col++) {
            pi.set(i);
            pj.set(j_col);
            Halide::Buffer<num_t> tmp = update_L.realize();
            // A[i][j_col] -> A(j_col, i)
            A(j_col, i) = tmp();
        }

        // U-part: j >= i, computed as a full row in one call.
        // We compute all j in [0, n) and then only store j >= i.
        pi.set(i);
        update_U_row.realize(u_row_tmp);
        for (int j_col = i; j_col < n; j_col++) {
            A(j_col, i) = u_row_tmp(j_col);
        }

        // Maintain reciprocal of diagonal for later L-updates and back-sub.
        diag_inv(i) = static_cast<num_t>(1.0) / A(i, i);
    }

    // Forward substitution to compute y
    for (int i = 0; i < n; i++) {
        pi.set(i);
        Halide::Buffer<num_t> tmp = compute_y.realize();
        y(i) = tmp();
    }

    // Back substitution to compute x
    for (int i = n - 1; i >= 0; i--) {
        pi.set(i);
        Halide::Buffer<num_t> tmp = compute_x.realize();
        x(i) = tmp();
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result vector x, similar to print_array().
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            if (i % 20 == 0) {
                std::cerr << '\n';
            }
            std::cerr << x(i) << ' ';
        }
        std::cerr << '\n';
    }

    // Print timing (seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
