#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (PolyBench sizes & DATA_TYPE)
#include "defines.hpp"

// include benchmark-specific definitions (N, DATA_TYPE, etc)
#include "ludcmp.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize A, b, x, y the same way as the original C init_array().
 *
 * Original C:
 *   for i:
 *     x[i] = 0;
 *     y[i] = 0;
 *     b[i] = (i+1)/fn/2.0 + 4;
 *
 *   A initial lower-triangular construction, then:
 *     B = A * A^T;
 *     A = B;
 *
 * In this implementation:
 *   - A is a Buffer<num_t,2> of shape (n, n) with indices A(col, row)
 *     so that for a fixed row, varying the column index accesses
 *     contiguous memory (good locality for our later loops).
 */
static void init_array(int n,
                       Halide::Buffer<num_t, 2> &A,   // shape (n, n): (x=col, y=row)
                       Halide::Buffer<num_t, 1> &b,   // shape (n)
                       Halide::Buffer<num_t, 1> &x,   // shape (n)
                       Halide::Buffer<num_t, 1> &y) { // shape (n)
    Var i("i"), col("col"), row("row");

    // ------------------------------------------------------------------
    // Initialize x and y to 0, b[i] = (i+1)/n/2 + 4
    // ------------------------------------------------------------------
    Func init_x("init_x"), init_y("init_y"), init_b("init_b");

    Expr n_expr = Expr(n);
    Expr inv_n  = cast<num_t>(Expr(1.0)) / cast<num_t>(n_expr);

    init_x(i) = cast<num_t>(Expr(0.0));
    init_y(i) = cast<num_t>(Expr(0.0));

    // b[i] = ((i+1) * (1/n)) / 2 + 4
    Expr term = cast<num_t>(i + 1) * inv_n;
    init_b(i) = term * cast<num_t>(Expr(0.5)) + cast<num_t>(Expr(4.0));

    init_x.realize(x);
    init_y.realize(y);
    init_b.realize(b);

    // ------------------------------------------------------------------
    // Initial lower-triangular A, with:
    //   A[i][j] = (-j % n) / n + 1 for j <= i, 0 otherwise, and A[i][i] = 1.
    //
    // We store A(row=i, col=j) at A(j, i), i.e., first dimension is column,
    // second is row. This makes varying 'col' contiguous in memory.
    // ------------------------------------------------------------------
    Func A_init("A_init");

    // (-j % n) / n + 1  -> implement as - (j % n) / n + 1
    Expr neg_mod = -(col % n);
    Expr base = cast<num_t>(neg_mod) / cast<num_t>(n_expr) + cast<num_t>(Expr(1.0));

    A_init(col, row) =
        select(col == row,
               cast<num_t>(Expr(1.0)),                        // diagonal = 1
               select(col <= row,
                      base,                                   // lower triangle
                      cast<num_t>(Expr(0.0))));               // upper triangle = 0

    // ------------------------------------------------------------------
    // Make the matrix positive semi-definite: B = A * A^T, then A = B.
    //
    // B[r][s] = sum_t A[r][t] * A[s][t]
    // In our layout: A(row=r, col=s) is A_init(s, r), so:
    // B(row=r, col=s) = sum_t A_init(t, r) * A_init(t, s)
    // We compute SPD(col, row) and then realize into A(col, row).
    // ------------------------------------------------------------------
    Func SPD("SPD");
    RDom t_dom(0, n, "t_dom");

    SPD(col, row) = cast<num_t>(Expr(0.0));
    SPD(col, row) += A_init(t_dom, row) * A_init(t_dom, col);

    // Simple but effective schedule for SPD:
    //   - parallelize across rows,
    //   - vectorize across columns,
    //   - vectorize the reduction over t_dom.
    Target init_target = get_jit_target_from_environment();
    const int vec = init_target.natural_vector_size(type_of<num_t>());

    SPD.compute_root()
       .parallel(row)
       .vectorize(col, vec);

    SPD.update()
       .reorder(t_dom, col, row)
       .parallel(row)
       .vectorize(t_dom, vec);

    SPD.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers:
    // A: 2D (n x n), first dimension = column (j), second = row (i)
    // b, x, y: 1D (n)
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 1> b(n), x(n), y(n);

    // Initialize data
    init_array(n, A, b, x, y);

    // --------------------------------------------------------------------
    // Set up Halide parameters and ImageParams for the kernel.
    // --------------------------------------------------------------------
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam b_param(type_of<num_t>(), 1, "b_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");
    ImageParam y_param(type_of<num_t>(), 1, "y_param");

    // Extra buffer & ImageParam for reciprocals of diagonal entries of U.
    // This replaces many divisions inside the LU and back-substitution
    // with cheaper multiplications.
    Halide::Buffer<num_t, 1> diag_inv(n);
    ImageParam diag_inv_param(type_of<num_t>(), 1, "diag_inv_param");

    Param<int> pi("pi");  // current row index i
    Param<int> pj("pj");  // current column index j
    Param<int> pn("pn");  // n (for convenience in ranges)

    A_param.set(A);
    b_param.set(b);
    x_param.set(x);
    y_param.set(y);
    diag_inv_param.set(diag_inv);
    pn.set(n);

    // --------------------------------------------------------------------
    // Halide helpers for the LU decomposition and forward/back substitution
    //
    // We follow the scalar algorithm:
    //
    //   for i = 0..n-1:
    //     # L-part (j < i)
    //     for j = 0..i-1:
    //       w = A[i][j]
    //       for k = 0..j-1: w -= A[i][k] * A[k][j]
    //       A[i][j] = w / A[j][j]
    //
    //     # U-part (j >= i)
    //     for j = i..n-1:
    //       w = A[i][j]
    //       for k = 0..i-1: w -= A[i][k] * A[k][j]
    //       A[i][j] = w
    //
    //   # Forward substitution:
    //   for i = 0..n-1:
    //     y[i] = b[i] - sum_{j=0..i-1} A[i][j] * y[j]
    //
    //   # Backward substitution:
    //   for i = n-1..0:
    //     x[i] = (y[i] - sum_{j=i+1..n-1} A[i][j] * x[j]) / A[i][i]
    //
    // Our storage is A_param(col=j, row=i).
    // We implement each scalar step as a small Halide pipeline,
    // driven by host-side loops (to respect loop-carried dependencies).
    // --------------------------------------------------------------------

    // 1) L-part update:
    //
    //   w = A[i][j] - sum_{k=0..j-1} A[i][k] * A[k][j];
    //   A[i][j] = w / A[j][j];
    //
    // We rewrite this as:
    //   A[i][j] = (A[i][j] - sum_{k=0..j-1} A[i][k] * A[k][j]) * (1 / A[j][j])
    //
    // and store 1 / A[j][j] in diag_inv[j] once when row j is finished.
    // This reduces the number of divisions from O(n^2) to O(n) while
    // preserving the original math up to usual FP roundoff.
    //
    // In our layout: A[i][j] == A_param(j, i).
    Func update_L("update_L");
    RDom rL(0, pj, "rL");
    Expr sum_L = sum(A_param(rL, pi) * A_param(pj, rL));
    update_L() = (A_param(pj, pi) - sum_L) * diag_inv_param(pj);

    // 2) U-part update:
    //
    //   w = A[i][j];
    //   for k = 0..i-1: w -= A[i][k] * A[k][j];
    //   A[i][j] = w;
    //
    // In our layout: A[i][j] == A_param(j, i).
    Func update_U("update_U");
    RDom rU(0, pi, "rU");
    Expr sum_U = sum(A_param(rU, pi) * A_param(pj, rU));
    update_U() = A_param(pj, pi) - sum_U;

    // 3) Forward substitution for y:
    //
    //   y[i] = b[i] - sum_{j=0..i-1} A[i][j] * y[j].
    //
    // In our layout: A[i][j] == A_param(j, i).
    Func compute_y("compute_y");
    RDom rY(0, pi, "rY");
    Expr sum_Y = sum(A_param(rY, pi) * y_param(rY));
    compute_y() = b_param(pi) - sum_Y;

    // 4) Back substitution for x:
    //
    //   x[i] = (y[i] - sum_{j=i+1..n-1} A[i][j] * x[j]) / A[i][i].
    //
    // We'll use the same diag_inv[i] = 1 / A[i][i] trick:
    //
    //   x[i] = (y[i] - sum_j A[i][j] * x[j]) * diag_inv[i].
    //
    // In our layout: A[i][j] == A_param(j, i).
    Func compute_x("compute_x");
    RDom rX(pi + 1, pn - (pi + 1), "rX"); // j runs from i+1 to n-1 (possibly empty)
    Expr sum_X = sum(A_param(rX, pi) * x_param(rX));
    compute_x() = (y_param(pi) - sum_X) * diag_inv_param(pi);

    // --------------------------------------------------------------------
    // Schedule the small helper pipelines
    //
    // We vectorize across the reduction variable in each pipeline to
    // exploit SIMD for the dot-products. The outer (scalar) parts are
    // driven from C++ loops.
    // --------------------------------------------------------------------
    Target kernel_target = get_jit_target_from_environment();
    const int vec_k = kernel_target.natural_vector_size(type_of<num_t>());

    // For each reduction update stage, vectorize over the reduction var.
    update_L.update()
            .vectorize(rL, vec_k);
    update_U.update()
            .vectorize(rU, vec_k);
    compute_y.update()
             .vectorize(rY, vec_k);
    compute_x.update()
             .vectorize(rX, vec_k);

    // Compile the small helper pipelines once for the chosen target.
    update_L.compile_jit(kernel_target);
    update_U.compile_jit(kernel_target);
    compute_y.compile_jit(kernel_target);
    compute_x.compile_jit(kernel_target);

    // ------------------------------------
    // Run the kernel and measure its time.
    // ------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // --------------------------------------------------------------------
    // LU decomposition (in-place A -> L and U, with diag_inv holding 1/U[j,j])
    // --------------------------------------------------------------------
    for (int i = 0; i < n; i++) {
        // L-part: j < i
        //
        // Each update_L() call computes a scalar A[i][j] using a
        // vectorized reduction across k, and multiplies by diag_inv[j].
        for (int j = 0; j < i; j++) {
            pi.set(i);
            pj.set(j);
            Halide::Buffer<num_t> tmp = update_L.realize();
            // A[i][j] -> A(j, i)
            A(j, i) = tmp();
        }

        // U-part: j >= i
        //
        // For a fixed i, the columns j >= i are independent given the
        // completed L row i, so this part is trivially parallel in j
        // at the algorithm level. Here we still drive it sequentially
        // from C++, but each scalar uses a vectorized reduction.
        for (int j = i; j < n; j++) {
            pi.set(i);
            pj.set(j);
            Halide::Buffer<num_t> tmp = update_U.realize();
            A(j, i) = tmp();
        }

        // Maintain reciprocal of diagonal entry for use in later L-rows
        // and in the back-substitution. This avoids repeated divisions
        // by A[i][i] inside the Halide pipelines.
        diag_inv(i) = static_cast<num_t>(1.0) / A(i, i);
    }

    // --------------------------------------------------------------------
    // Forward substitution to compute y: L * y = b
    // --------------------------------------------------------------------
    for (int i = 0; i < n; i++) {
        pi.set(i);
        Halide::Buffer<num_t> tmp = compute_y.realize();
        y(i) = tmp();
    }

    // --------------------------------------------------------------------
    // Back substitution to compute x: U * x = y
    // --------------------------------------------------------------------
    for (int i = n - 1; i >= 0; i--) {
        pi.set(i);
        Halide::Buffer<num_t> tmp = compute_x.realize();
        x(i) = tmp();
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result vector x, similar to print_array().
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            if (i % 20 == 0) {
                std::cerr << '\n';
            }
            std::cerr << x(i) << ' ';
        }
        std::cerr << '\n';
    }

    // Print timing (seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
