#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>
#include <vector>

#include "Halide.h"

// include common definitions (PolyBench sizes & DATA_TYPE)
#include "defines.hpp"

// include benchmark-specific definitions (N, DATA_TYPE, etc)
#include "ludcmp.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize A, b, x, y the same way as the original C init_array().
 *
 * Original C:
 *   for i:
 *     x[i] = 0;
 *     y[i] = 0;
 *     b[i] = (i+1)/fn/2.0 + 4;
 *
 *   A initial lower-triangular construction, then:
 *     B = A * A^T;
 *     A = B;
 *
 * Layout note:
 *   We conceptually treat A as row-major A[row][col], but physically store it
 *   as Buffer(num_t, 2) with A(col, row) (x = col, y = row), i.e. first
 *   dimension is column, second is row. This matches the original code.
 */
static void init_array(int n,
                       Halide::Buffer<num_t, 2> &A,   // shape (n, n): (x=col, y=row)
                       Halide::Buffer<num_t, 1> &b,   // shape (n)
                       Halide::Buffer<num_t, 1> &x,   // shape (n)
                       Halide::Buffer<num_t, 1> &y) { // shape (n)
    Var i("i"), col("col"), row("row");

    // -------------------------------
    // Initialize x, y, b
    // -------------------------------
    Func init_x("init_x"), init_y("init_y"), init_b("init_b");

    Expr n_expr = Expr(n);

    init_x(i) = cast<num_t>(Expr(0.0));
    init_y(i) = cast<num_t>(Expr(0.0));

    // b[i] = ((i+1)/n)/2 + 4
    // Compute in num_t to match the original C.
    Expr term1 = cast<num_t>(i + 1) / cast<num_t>(n_expr);
    Expr term2 = term1 / cast<num_t>(Expr(2.0));
    Expr term3 = term2 + cast<num_t>(Expr(4.0));
    init_b(i) = term3;

    // Choose a reasonable vector width for this target.
    Target target = get_host_target();
    int vec = target.natural_vector_size(type_of<num_t>());

    // Simple 1D schedule: vectorize and parallelize the initialization of x, y, b.
    init_x
        .vectorize(i, vec)
        .parallel(i);
    init_y
        .vectorize(i, vec)
        .parallel(i);
    init_b
        .vectorize(i, vec)
        .parallel(i);

    init_x.realize(x);
    init_y.realize(y);
    init_b.realize(b);

    // ---------------------------------------------------
    // Initial lower-triangular matrix A_init:
    //
    // A_init[row=i, col=j] = (-j % n) / n + 1 for j <= i,
    //                      = 0              for j >  i,
    // and with diagonal A_init[i][i] = 1.
    //
    // We store A(row=i, col=j) at A(j, i), i.e., first dimension is
    // column, second is row.
    // ---------------------------------------------------
    Func A_init("A_init");

    // (-j % n) / n + 1  -> implement as - (j % n) / n + 1
    Expr neg_mod = -(col % n);
    Expr base = cast<num_t>(neg_mod) / cast<num_t>(n_expr) + cast<num_t>(Expr(1.0));

    A_init(col, row) =
        select(col == row,
               cast<num_t>(Expr(1.0)),                      // diagonal = 1
               select(col <= row,
                      base,                                 // lower triangle
                      cast<num_t>(Expr(0.0))));             // upper triangle = 0

    // ---------------------------------------------------
    // Make the matrix symmetric positive (semi-)definite:
    //   B = A_init * A_init^T, then A = B.
    //
    // B[r][s] = sum_t A_init[r][t] * A_init[s][t]
    // In our layout: A(row=r, col=s) is stored as A(s, r), so:
    // B(row=r, col=s) = sum_t A_init(t, r) * A_init(t, s)
    // ---------------------------------------------------
    Func SPD("SPD");
    RDom t_dom(0, n, "t_dom");

    SPD(col, row) = cast<num_t>(Expr(0.0));
    SPD(col, row) += A_init(t_dom, row) * A_init(t_dom, col);

    // Schedule SPD for better cache locality and SIMD usage.
    {
        Var xo("xo"), yo("yo"), xi("xi"), yi("yi");
        RVar t_outer("t_outer"), t_inner("t_inner");

        const int tile = 32;

        // Tile the (col,row) domain and parallelize over tiles in the
        // slow row dimension. Vectorize along the inner column dimension.
        SPD
            .compute_root()
            .tile(col, row, xo, yo, xi, yi, tile, tile)
            .parallel(yo)
            .vectorize(xi, vec);

        // Vectorize the reduction over t_dom. We split the reduction
        // variable and vectorize the inner piece; Halide will handle
        // the tail for non-multiples of 'vec'.
        SPD.update()
            .split(t_dom, t_outer, t_inner, vec)
            .reorder(t_inner, xi, yi, xo, yo)
            .vectorize(t_inner)
            .unroll(t_inner);
    }

    // Realize SPD into A buffer (shape n x n, (col, row)).
    SPD.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers:
    // A: 2D (n x n), first dimension = column (j), second = row (i)
    // b, x, y: 1D (n)
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 1> b(n), x(n), y(n);

    // Extra host-side buffer for reciprocals of diagonal entries of U:
    // diag_inv[i] = 1 / A[i][i]. This lets us replace many divisions
    // by multiplications (one division per row instead of ~O(n^2)).
    std::vector<num_t> diag_inv(n);

    // Initialize data (x, y, b, and SPD matrix A).
    init_array(n, A, b, x, y);

    // Set up Halide parameters and ImageParams for the kernel.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam b_param(type_of<num_t>(), 1, "b_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");
    ImageParam y_param(type_of<num_t>(), 1, "y_param");

    Param<int> pi("pi");               // current row index i
    Param<int> pj("pj");               // current column index j (for scalar L update)
    Param<int> pn("pn");               // n (for convenience in ranges)
    Param<num_t> p_diag("p_diag");     // current 1 / A[j][j] or 1 / A[i][i] for L/X

    A_param.set(A);
    b_param.set(b);
    x_param.set(x);
    y_param.set(y);
    pn.set(n);

    // --------------------------------------------------------------------
    // Halide helpers for the LU decomposition and forward/back substitution
    // --------------------------------------------------------------------

    // Target & natural SIMD width for scheduling.
    Target target = get_host_target();
    int vec = target.natural_vector_size(type_of<num_t>());

    // --------------------------------------------------------------------
    // 1) L-part update (scalar per (i,j), j < i)
    //
    // For fixed (i,j), with j < i:
    //   w = A[i][j];
    //   for k = 0..j-1: w -= A[i][k] * A[k][j];
    //   A[i][j] = w / A[j][j];
    //
    // We algebraically transform this to:
    //   A[i][j] = (A[i][j] - sum_{k=0..j-1} A[i][k]*A[k][j]) * diag_inv[j],
    // where diag_inv[j] = 1 / A[j][j] was computed when row j was completed.
    //
    // Layout: A[i][j] == A_param(j, i).
    // --------------------------------------------------------------------
    Func update_L("update_L");
    {
        RDom rL(0, pj, "rL");
        Expr sum_L = sum(A_param(rL, pi) * A_param(pj, rL));
        update_L() = (A_param(pj, pi) - sum_L) * p_diag;
    }

    // Vectorize the reduction over k (rL) inside the scalar L update.
    {
        RVar rL_outer("rL_outer"), rL_inner("rL_inner");
        update_L.update()
            .split(update_L.update().rvars()[0], rL_outer, rL_inner, vec)
            .vectorize(rL_inner);
    }

    // --------------------------------------------------------------------
    // 2) U-part update, batched over all j >= i in a single Func.
    //
    // For fixed row i and any j >= i:
    //   w = A[i][j];
    //   for k = 0..i-1: w -= A[i][k] * A[k][j];
    //   A[i][j] = w;
    //
    // Layout: A[i][j] == A_param(j, i).
    //
    // We define a row-wise Func row_U(j) that computes the updated
    // values for all columns j in the current row i in one call. This
    // allows Halide to parallelize and vectorize across j inside the
    // row, while we keep the outer i-loop in C++ to respect
    // dependencies between rows.
    // --------------------------------------------------------------------
    Var j_u("j_u");
    Func row_U("row_U");
    {
        RDom rU(0, pi, "rU");
        Expr sum_U = sum(A_param(rU, pi) * A_param(j_u, rU));
        row_U(j_u) = A_param(j_u, pi) - sum_U;
    }

    // Schedule row_U:
    //   - parallelize over tiles of j to use many cores
    //   - vectorize within each tile
    //   - vectorize the k-reduction as well
    {
        Var jo("jo"), ji("ji");
        RVar rU_outer("rU_outer"), rU_inner("rU_inner");
        const int j_tile = 64;

        row_U
            .compute_root()
            .split(j_u, jo, ji, j_tile)
            .parallel(jo)
            .vectorize(ji, vec);

        row_U.update()
            .split(row_U.update().rvars()[0], rU_outer, rU_inner, vec)
            .vectorize(rU_inner);
    }

    // --------------------------------------------------------------------
    // 3) Forward substitution for y:
    //
    // For i = 0..n-1:
    //   y[i] = b[i] - sum_{j=0..i-1} A[i][j] * y[j].
    //
    // Layout: A[i][j] == A_param(j, i).
    // --------------------------------------------------------------------
    Func compute_y("compute_y");
    {
        RDom rY(0, pi, "rY");
        Expr sum_Y = sum(A_param(rY, pi) * y_param(rY));
        compute_y() = b_param(pi) - sum_Y;

        // Vectorize the reduction over rY.
        RVar rY_outer("rY_outer"), rY_inner("rY_inner");
        compute_y.update()
            .split(compute_y.update().rvars()[0], rY_outer, rY_inner, vec)
            .vectorize(rY_inner);
    }

    // --------------------------------------------------------------------
    // 4) Back substitution for x:
    //
    // For i = n-1..0:
    //   x[i] = (y[i] - sum_{j=i+1..n-1} A[i][j] * x[j]) / A[i][i].
    //
    // Using diag_inv[i] = 1 / A[i][i], this becomes:
    //   x[i] = (y[i] - sum_{j=i+1..n-1} A[i][j] * x[j]) * diag_inv[i].
    //
    // Layout: A[i][j] == A_param(j, i).
    // --------------------------------------------------------------------
    Func compute_x("compute_x");
    {
        // Domain j = i+1 .. n-1  -> RDom(pi+1, n-(pi+1))
        RDom rX(pi + 1, pn - (pi + 1), "rX");
        Expr sum_X = sum(A_param(rX, pi) * x_param(rX));
        compute_x() = (y_param(pi) - sum_X) * p_diag;

        // Vectorize the reduction over rX.
        RVar rX_outer("rX_outer"), rX_inner("rX_inner");
        compute_x.update()
            .split(compute_x.update().rvars()[0], rX_outer, rX_inner, vec)
            .vectorize(rX_inner);
    }

    // Compile the small helper pipelines once with the chosen target.
    update_L.compile_jit(target);
    row_U.compile_jit(target);
    compute_y.compile_jit(target);
    compute_x.compile_jit(target);

    // ------------------------------------
    // Run the kernel and measure its time.
    // ------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // Temporary 1D buffer used to hold the updated U row for each i.
    // We will realize row_U into a cropped view of this buffer, so that
    // only j in [i, n) are computed.
    Halide::Buffer<num_t, 1> row_buffer(n);

    // LU decomposition
    for (int i = 0; i < n; i++) {
        // -----------------------------
        // L-part: j < i (strictly lower)
        // -----------------------------
        for (int j = 0; j < i; j++) {
            pi.set(i);
            pj.set(j);
            // diag_inv[j] was computed after finishing row j.
            p_diag.set(diag_inv[j]);

            Halide::Buffer<num_t> tmp = update_L.realize();
            // A[i][j] -> A(j, i)
            A(j, i) = tmp();
        }

        // -----------------------------
        // U-part: j >= i (upper + diagonal)
        // Compute the entire row i of U in one Halide call, for all j in [i, n).
        // -----------------------------
        pi.set(i);

        // Create a cropped view of row_buffer over j in [i, n).
        Halide::Buffer<num_t, 1> row_view = row_buffer.cropped(0, i, n - i);

        // row_U(j) uses the up-to-date L(i, k) (stored in A) and previous rows.
        row_U.realize(row_view);

        // Copy the updated row from row_view back into A.
        for (int j = i; j < n; j++) {
            A(j, i) = row_view(j);
        }

        // Cache reciprocal of the diagonal for future L-updates and back-substitution.
        diag_inv[i] = (num_t)1.0 / A(i, i);
    }

    // Forward substitution to compute y
    for (int i = 0; i < n; i++) {
        pi.set(i);
        Halide::Buffer<num_t> tmp = compute_y.realize();
        y(i) = tmp();
    }

    // Back substitution to compute x
    for (int i = n - 1; i >= 0; i--) {
        pi.set(i);
        p_diag.set(diag_inv[i]);
        Halide::Buffer<num_t> tmp = compute_x.realize();
        x(i) = tmp();
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result vector x, similar to print_array().
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            if (i % 20 == 0) {
                std::cerr << '\n';
            }
            std::cerr << x(i) << ' ';
        }
        std::cerr << '\n';
    }

    // Print timing (seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
