```cpp
#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (PolyBench sizes & DATA_TYPE)
#include "defines.hpp"

// include benchmark-specific definitions (N, DATA_TYPE, etc)
#include "ludcmp.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize A, b, x, y the same way as the original C init_array().
 *
 * Original C:
 *   for i:
 *     x[i] = 0;
 *     y[i] = 0;
 *     b[i] = (i+1)/fn/2.0 + 4;
 *
 *   A initial lower-triangular construction, then:
 *     B = A * A^T;
 *     A = B;
 *
 * We keep the same mathematics but implement it with Halide Funcs.
 * The matrix is stored in row-major order logically as A[row=i][col=j],
 * mapped to a Halide Buffer as A(j, i) (x = col, y = row), so rows are
 * contiguous in memory.
 */
static void init_array(int n,
                       Halide::Buffer<num_t, 2> &A,   // shape (n, n): (x=col, y=row)
                       Halide::Buffer<num_t, 1> &b,   // shape (n)
                       Halide::Buffer<num_t, 1> &x,   // shape (n)
                       Halide::Buffer<num_t, 1> &y) { // shape (n)
    Var i("i"), col("col"), row("row");

    // Initialize x and y to 0, b[i] = (i+1)/n/2 + 4
    Func init_x("init_x"), init_y("init_y"), init_b("init_b");

    Expr n_expr = Expr(n);

    init_x(i) = cast<num_t>(Expr(0.0));
    init_y(i) = cast<num_t>(Expr(0.0));

    // term = (i+1)/n/2 + 4 in num_t
    Expr term1 = cast<num_t>(i + 1) / cast<num_t>(n_expr);
    Expr term2 = term1 / cast<num_t>(Expr(2.0));
    Expr term3 = term2 + cast<num_t>(Expr(4.0));
    init_b(i) = term3;

    init_x.realize(x);
    init_y.realize(y);
    init_b.realize(b);

    // Initial lower-triangular A, with A[i][j] = (-j % n) / n + 1 for j <= i, 0 otherwise,
    // and A[i][i] = 1.
    //
    // We store A(row=i, col=j) at A(j, i), i.e., first dimension is column, second is row.
    Func A_init("A_init");

    Expr neg_mod = -(col % n);
    Expr base = cast<num_t>(neg_mod) / cast<num_t>(n_expr) + cast<num_t>(Expr(1.0));

    A_init(col, row) =
        select(col == row,
               cast<num_t>(Expr(1.0)),                      // diagonal = 1
               select(col <= row,
                      base,                                 // lower triangle
                      cast<num_t>(Expr(0.0))));             // upper triangle = 0

    // Make the matrix symmetric positive semi-definite: B = A * A^T, then A = B.
    //
    // B[r][s] = sum_t A[r][t] * A[s][t]
    // In our layout: A(r, t) is A[row=r, col=t] stored at (x=t, y=r),
    // so:
    //   B(row=r, col=s) = sum_t A_init(t, r) * A_init(t, s)
    Func SPD("SPD");
    RDom t_dom(0, n, "t_dom");

    SPD(col, row) = cast<num_t>(Expr(0.0));
    SPD(col, row) += A_init(t_dom, row) * A_init(t_dom, col);

    // Simple but effective schedule for SPD (not in timed region, but cheap to improve):
    {
        Target t = get_host_target();
        int vec = t.natural_vector_size<num_t>();

        Var xo("xo"), yo("yo"), xi("xi"), yi("yi");
        SPD
            .tile(col, row, xo, yo, xi, yi, 32, 32)
            .vectorize(xi, vec)
            .parallel(yo);
    }

    // Realize SPD into A buffer (shape n x n).
    SPD.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers:
    // A: 2D (n x n), first dimension = column (j), second = row (i)
    // b, x, y: 1D (n)
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 1> b(n), x(n), y(n);

    // Extra 1D buffer to store 1 / A[i][i] (diagonal reciprocals of U)
    // This turns many divisions into multiplications in the L-update and
    // back-substitution phases.
    Halide::Buffer<num_t, 1> diag_inv(n);

    // Initialize data
    init_array(n, A, b, x, y);

    // Set up Halide parameters and ImageParams for the kernel.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam b_param(type_of<num_t>(), 1, "b_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");
    ImageParam y_param(type_of<num_t>(), 1, "y_param");
    ImageParam diag_param(type_of<num_t>(), 1, "diag_param"); // holds 1 / A[i][i]

    Param<int> pi("pi");  // current row index i
    Param<int> pj("pj");  // current column index j (for scalar L updates)
    Param<int> pn("pn");  // n (for convenience in ranges)

    A_param.set(A);
    b_param.set(b);
    x_param.set(x);
    y_param.set(y);
    diag_param.set(diag_inv);
    pn.set(n);

    // --------------------------------------------------------------------
    // Halide helpers for LU decomposition and forward/back substitution
    //
    // We follow the scalar PolyBench ludcmp algorithm, but:
    //  - Use Halide for the inner dot-products.
    //  - Use an extra diag_inv[i] = 1 / A[i][i] array to replace
    //    repeated divisions by multiplications.
    //  - For the U-part we update an entire row segment in one Halide
    //    call, exposing vectorization and parallelism over j.
    //
    // Logical layout: A[i][j] is matrix row i, column j.
    // Buffer layout:  A(j, i) (x = col, y = row).
    // A_param(col, row) is thus A[row][col].
    // --------------------------------------------------------------------

    // 1) L-part scalar update:
    //
    // For j < i:
    //   w = A[i][j] - sum_{k=0..j-1} A[i][k] * A[k][j];
    //   A[i][j] = w / A[j][j]  == w * diag_inv[j].
    //
    // In buffer coordinates: A[i][j] == A_param(j, i).
    Func update_L("update_L");
    {
        RDom rL(0, pj, "rL");  // k from 0..j-1, j is pj
        Expr sum_L = sum(A_param(rL, pi) * A_param(pj, rL));
        update_L() = (A_param(pj, pi) - sum_L) * diag_param(pj);
    }

    // 2) U-part row update:
    //
    // For j >= i:
    //   w = A[i][j] - sum_{k=0..i-1} A[i][k] * A[k][j];
    //   A[i][j] = w;
    //
    // There are no dependencies between different j in the same row i,
    // so we can update the whole row segment j ∈ [i, n) at once.
    //
    // Buffer coordinates: A[i][j] = A_param(j, i).
    // We parameterize on the row index pi and use j_var to represent
    // columns starting at pi (j = pi + j_var).
    Var j_var("j_var");
    Func update_U_row("update_U_row");
    {
        RDom rU(0, pi, "rU");  // k from 0..i-1
        Expr col_index = j_var + pi;  // actual column j = i + j_var

        Expr sum_U = sum(A_param(rU, pi) * A_param(col_index, rU));
        update_U_row(j_var) = A_param(col_index, pi) - sum_U;
    }

    // 3) Forward substitution for y:
    //
    // For i = 0..n-1:
    //   y[i] = b[i] - sum_{j=0..i-1} A[i][j] * y[j].
    //
    // In buffer coordinates: A[i][j] == A_param(j, i).
    Func compute_y("compute_y");
    {
        RDom rY(0, pi, "rY");  // j from 0..i-1
        Expr sum_Y = sum(A_param(rY, pi) * y_param(rY));
        compute_y() = b_param(pi) - sum_Y;
    }

    // 4) Back substitution for x:
    //
    // For i = n-1..0:
    //   x[i] = (y[i] - sum_{j=i+1..n-1} A[i][j] * x[j]) / A[i][i]
    //        = (y[i] - sum_{j=i+1..n-1} A[i][j] * x[j]) * diag_inv[i].
    //
    // In buffer coordinates: A[i][j] == A_param(j, i).
    Func compute_x("compute_x");
    {
        // Domain j = i+1 .. n-1  -> RDom(pi+1, n-(pi+1))
        RDom rX(pi + 1, pn - (pi + 1), "rX");
        Expr sum_X = sum(A_param(rX, pi) * x_param(rX));
        compute_x() = (y_param(pi) - sum_X) * diag_param(pi);
    }

    // -----------------------------
    // Schedule the Halide helpers.
    // -----------------------------
    Target target = get_host_target();
    int vec_width = target.natural_vector_size<num_t>();

    // update_U_row operates over j_var; vectorize and parallelize across j_var
    // to leverage SIMD and multiple cores on each row update.
    update_U_row
        .vectorize(j_var, vec_width)
        .parallel(j_var);

    // The other helpers (update_L / compute_y / compute_x) are scalar or
    // 0-D pipelines driven by host loops over i,j, so there is little
    // scheduling to do beyond JIT compilation.

    // Compile the small helper pipelines once.
    update_L.compile_jit(target);
    update_U_row.compile_jit(target);
    compute_y.compile_jit(target);
    compute_x.compile_jit(target);

    // ------------------------------------
    // Run the kernel and measure its time.
    // ------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // LU decomposition
    for (int i = 0; i < n; i++) {
        // --- L-part: j < i ---
        //
        // Each L update depends on previously computed L entries in this row
        // and on completed rows < i, so we keep this loop sequential in j.
        for (int j = 0; j < i; j++) {
            pi.set(i);
            pj.set(j);
            Halide::Buffer<num_t> tmp = update_L.realize();
            // A[i][j] -> A(j, i) in our buffer layout
            A(j, i) = tmp();
        }

        // --- U-part: j >= i ---
        //
        // For fixed i, all U[i][j] with j >= i are independent given row i
        // below the diagonal, so we update the entire row segment in one
        // Halide call, which is vectorized and parallelized over j.
        pi.set(i);

        int width = n - i;
        Halide::Buffer<num_t> row_update(width);
        update_U_row.realize(row_update);

        for (int ofs = 0; ofs < width; ++ofs) {
            int j = i + ofs;
            A(j, i) = row_update(ofs);
        }

        // Cache reciprocal of the diagonal A[i][i] to replace future
        // divisions by multiplications in L-updates and back-substitution.
        diag_inv(i) = static_cast<num_t>(1.0) / A(i, i);
    }

    // Forward substitution to compute y
    for (int i = 0; i < n; i++) {
        pi.set(i);
        Halide::Buffer<num_t> tmp = compute_y.realize();
        y(i) = tmp();
    }

    // Back substitution to compute x
    for (int i = n - 1; i >= 0; i--) {
        pi.set(i);
        Halide::Buffer<num_t> tmp = compute_x.realize();
        x(i) = tmp();
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result vector x, similar to print_array().
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            if (i % 20 == 0) {
                std::cerr << '\n';
            }
            std::cerr << x(i) << ' ';
        }
        std::cerr << '\n';
    }

    // Print timing (seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
